const result = $memory.getJson('ventasResult', {});
let accion = (result.accion || 'continuar').toLowerCase();
if (accion === 'test_drive' || accion === 'financiamiento') accion = 'asesor';
$memory.set('accion_ventas', accion);
if (result.busqueda) $memory.set('busqueda_productos', String(result.busqueda));
if (result.ciudad) $memory.set('ciudad_usuario', String(result.ciudad));
if (result.modelo_interes) $memory.set('modelo_interes', String(result.modelo_interes));
if (result.agencia_solicitada) $memory.set('agencia_solicitada', String(result.agencia_solicitada));
if (result.motivo) $memory.set('motivo_ventas', String(result.motivo));

const catalogo = $memory.getJson('catalogo_modelos', []);
const busqueda = String($memory.get('busqueda_productos') || $memory.get('modelo_interes') || '').toLowerCase().trim();
const palabras = busqueda.split(/\s+/).filter(Boolean);
const fallbackImg = 'https://www.vehicentro.com/wp-content/uploads/2021/06/logo-vehicentro.png';

function textoModelo(m) {
  return [m.nombre_modelo, m.nombre_segmento, m.caracteristicas, m.nombre_marca].filter(Boolean).join(' ').toLowerCase();
}

function obtenerImagen(m) {
  const imgs = m.imagenes || m.imagen || m.media || [];
  if (Array.isArray(imgs) && imgs.length) {
    const first = imgs[0];
    if (typeof first === 'string') return first.split(',')[0].trim() || fallbackImg;
    if (first && (first.url || first.link)) return first.url || first.link;
  }
  if (typeof imgs === 'string' && imgs) {
    const first = imgs.split(',').map(function(s) { return s.trim(); }).filter(Boolean)[0];
    return first || fallbackImg;
  }
  return fallbackImg;
}

function obtenerUrl(m) {
  return m.web_modelo || m.url_modelo || m.url || m.link || m.web_agencia || 'https://www.vehicentro.com';
}

function coincide(m) {
  const texto = textoModelo(m);
  if (!palabras.length) return true;
  return palabras.every(function(p) { return texto.indexOf(p) >= 0; });
}

let filtrados = catalogo.filter(coincide);
if (filtrados.length < 2 && palabras.length) {
  filtrados = catalogo.filter(function(m) {
    const texto = textoModelo(m);
    return palabras.some(function(p) { return texto.indexOf(p) >= 0; });
  });
}
if (filtrados.length < 2) filtrados = catalogo.slice(0, 10);

const cards = filtrados.slice(0, 10).map(function(m, i) {
  const nombre = m.nombre_modelo || m.modelo || ('Modelo ' + (i + 1));
  const moneda = m.moneda || 'USD';
  const precio = m.precio_venta ? ('$' + Number(m.precio_venta).toLocaleString('es-EC') + ' ' + moneda) : '';
  const segmento = m.nombre_segmento ? (' · ' + m.nombre_segmento) : '';
  let bodyText = precio ? (nombre + segmento + ' — ' + precio) : (nombre + segmento);
  if (bodyText.length > 160) bodyText = bodyText.substring(0, 157) + '...';
  return {
    type: 'cta_url',
    header: { type: 'image', image: { link: obtenerImagen(m) } },
    body: { text: bodyText },
    action: {
      name: 'cta_url',
      parameters: { display_text: 'Ver modelo', url: obtenerUrl(m) }
    }
  };
});

const intro = busqueda
  ? ('Estos modelos coinciden con tu búsqueda: *' + busqueda + '* 🚗')
  : 'Estos son nuestros modelos disponibles 🚗';

$memory.setJson('carousel_cards', cards, 3600);
$memory.set('carousel_intro', intro);
$memory.set('carousel_listo', cards.length >= 2 ? 'si' : 'no');

configuration.preRequestScript:
const cards = $memory.get('carousel_cards') || [];
const intro = $memory.get('carousel_intro') || 'Estos son nuestros modelos disponibles 🚗';
const userId = String($user.get('id') || '');
const payload = {
  type: 'CAROUSEL',
  userId: userId,
  text: intro,
  parameters: { cards: cards }
};
$memory.set('carousel_body', JSON.stringify(payload));

