const marcaActiva = $memory.get('marca_activa') || $memory.get('id_marca') || $memory.get('marca_seleccionada') || '0';
$memory.set('id_marca_ventas', String(marcaActiva));
const intencion = $memory.get('intencion_activa') || $memory.get('intencion_seleccionada') || 'ventas';
$memory.set('intencion_ventas', String(intencion));

const response = $context.getHttpResponse('agenciasResponse');
let data = {};
try {
  data = response.json();
} catch (e) {
  data = { items: [] };
}
const items = data.items || data.agencias || data.data || (Array.isArray(data) ? data : []);
const ciudad = ($memory.get('ciudad_usuario') || '').toLowerCase();
let filtradas = items;
if (ciudad) {
  filtradas = items.filter(function(a) {
    const c = (a.ciudad || a.city || a.nombre_ciudad || '').toLowerCase();
    return c.includes(ciudad) || ciudad.includes(c);
  });
  if (filtradas.length === 0) filtradas = items;
}
let texto = '';
filtradas.slice(0, 8).forEach(function(a, i) {
  const nombre = a.nombre || a.agencia || a.sucursal || 'Agencia ' + (i + 1);
  const dir = a.direccion || a.address || '';
  const horario = a.horario || a.horarios || '';
  texto += (i + 1) + '. *' + nombre + '*\n';
  if (dir) texto += '   📍 ' + dir + '\n';
  if (horario) texto += '   🕐 ' + horario + '\n';
  texto += '\n';
});
if (!texto) texto = 'No encontré agencias para tu ciudad. Un asesor te ayudará.';
$memory.set('listado_agencias', texto);

